Script:
# Allocate Workstation Automatically
# Trigger: Before Insert (Job Card)

# Run only if workstation is not already assigned
if not doc.workstation and doc.work_order and doc.operation:

    # Get BOM from Work Order
    bom_no = frappe.db.get_value(
        "Work Order",
        doc.work_order,
        "bom_no"
    )

    if bom_no:

        # Fetch matching BOM Operation
        bom_op = frappe.get_all(
            "BOM Operation",
            filters={
                "parent": bom_no,
                "operation": doc.operation
            },
            fields=[
                "workstation_type",
                "workstation"
            ],
            limit=1
        )

        if bom_op:

            row = bom_op[0]

            workstation_type = None

            # Prefer Workstation Type
            if row.get("workstation_type"):
                workstation_type = row.workstation_type

            # Otherwise derive from Workstation
            elif row.get("workstation"):
                workstation_type = frappe.db.get_value(
                    "Workstation",
                    row.workstation,
                    "workstation_type"
                )

            if workstation_type:

                # Get all workstations of this type
                candidates = frappe.get_all(
                    "Workstation",
                    filters={
                        "workstation_type": workstation_type
                    },
                    fields=["name"],
                    order_by="name asc"
                )

                if candidates:

                    # Select first workstation
                    selected_ws = candidates[0].name

                    # Assign workstation
                    doc.workstation = selected_ws

                    # Copy Plant Floor
                    plant_floor = frappe.db.get_value(
                        "Workstation",
                        selected_ws,
                        "plant_floor"
                    )

                    if plant_floor:
                        doc.custom_plant_floor = plant_floor

# Trigger only when trying to start the Job Card
if doc.status == "Work In Progress":

    jcs = frappe.get_all(
        "Job Card",
        filters={
            "work_order": doc.work_order,
            "docstatus": ["<", 2]
        },
        fields=["name", "idx", "status", "docstatus", "operation"],
        order_by="idx asc"
    )

    for jc in jcs:
        if jc.name == doc.name:
            break

        if jc.status != "Completed" or jc.docstatus != 1:
            frappe.throw(
                f"Cannot start this operation.<br><br>"
                f"Previous Job Card is not completed and submitted:<br>"
                f"<b>Job Card:</b> {jc.name}<br>"
                f"<b>Operation:</b> {jc.operation}"
            )

if doc.work_order:
    doc.custom_actual_production_qty = frappe.db.get_value(
        "Work Order",
        doc.work_order,
        "qty"
    ) or 0

# Trigger only when trying to start the Job Card
if doc.status == "Work In Progress":

    jcs = frappe.get_all(
        "Job Card",
        filters={
            "work_order": doc.work_order,
            "docstatus": ["<", 2]
        },
        fields=["name", "idx", "status", "docstatus", "operation"],
        order_by="idx asc"
    )

    for jc in jcs:
        if jc.name == doc.name:
            break

        # Must be Completed AND Submitted
        if jc.status != "Completed" or jc.docstatus != 1:

            frappe.throw(
                f"Cannot start this operation.  "
                f"Previous Job Card is not completed and submitted:<br>"
                f"<b>Job Card:</b> {jc.name}<br>"
                f"<b>Operation:</b> {jc.operation}"
            )
